import heapq
G = {
 'A': {'B':4,'C':2},
 'B': {'A':4,'C':1,'D':5},
 'C': {'A':2,'B':1,'D':8,'E':10},
 'D': {'B':5,'C':8,'E':2},
 'E': {'C':10,'D':2}
}
def dijkstra(s):
    dist = {v: float('inf') for v in G}
    pred = {v: None for v in G}
    dist[s] = 0
    pq = [(0, s)]
    settled = set()
    while pq:
        du, u = heapq.heappop(pq)
        if u in settled:
            continue
        if du != dist[u]:
            continue
        settled.add(u)
        for v, w in G[u].items():
            nd = du + w
            if nd < dist[v]:
                dist[v] = nd
                pred[v] = u
                heapq.heappush(pq, (nd, v))
    return dist, pred
dist, pred = dijkstra('A')
for v in ['A','B','C','D','E']:
    print(dist[v])
path = ['E']
while path[-1] != 'A':
    path.append(pred[path[-1]])
path.reverse()
cost = sum(G[path[i]][path[i+1]] for i in range(len(path)-1))
print(cost)
